function normalize(p){p.render_scene=normalizeRenderScene(p.render_scene);p.scene_coordinates={hard_point_mm:null,h_point_mm:null,...(p.scene_coordinates||{})};p.assets=(p.assets||[]).map(a=>({...a,render_config:normalizeRenderConfig(a.render_config)}));p.variables=p.variables||{};p.simulation={start_time:0,end_time:6,timestep:.01,...p.simulation};p.kinematic_closures=p.kinematic_closures||p.closures||[];p.layers=p.layers||[];const top=p.joints||[];p.layers.forEach(l=>{l.active=l.active!==false;l.color=l.color||'#8ea5bd';if(l.color.startsWith('#'))l.color=hexToRgba(l.color);l.position_mm=l.position_mm||[0,0,0];l.joints=l.joints||top.filter(j=>j.child_layer_id===l.id).map(j=>({...j,point:(j.point_mm||[0,0,0]).join(', '),axis:(j.axis||[0,0,1]).join(', ')}));l.meshes=l.meshes||[];l.meshes.forEach(m=>{if(!m.color_source)m.color_source=m.rgba&&rgbaToHex(m.rgba)!==rgbaToHex(l.color)?'mesh':'layer';if(m.render_config)m.render_config=normalizeRenderConfig(m.render_config);if(m.material_slots&&typeof m.material_slots==='object')m.material_slots=Object.fromEntries(Object.entries(m.material_slots).map(([slot,cfg])=>[slot,normalizeRenderConfig(cfg)]))});if(!l.meshes.length&&l.asset_id){const a=(p.assets||[]).find(x=>x.id===l.asset_id);if(a)l.meshes=[{id:uid('mesh'),filename:a.name,asset_id:a.id,rgba:'',color_source:'layer',opacity:1,collision:false}]}});const legacy=(p.drives||[]).map(d=>({...d,enabled:d.enabled!==false,segments:d.segments||(d.actions||[]).map((a,i)=>({id:a.id||uid('motion'),name:a.name||`动作${i+1}`,travel:Number(a.target||0),profile:'s_curve'}))}));if(!Array.isArray(p.activity_parts)){p.activity_parts=legacy.map(d=>({id:uid('part'),name:d.name||'活动部位',enabled:d.enabled!==false,motions:(d.segments||[]).map((s,i)=>({id:s.id||uid('motion'),name:s.name||`动作${i+1}`,joint_id:d.joint_id||'',position_0_percent:Number(d.initial_position??d.reverse_limit??0),position_100_percent:Number(d.initial_position??d.reverse_limit??0)+Number(s.travel||0),mode:s.profile==='mapping'?'mapping':'ease',rated_speed:Number(s.speed||d.rated_speed||30),enabled:true}))}))}p.activity_parts=p.activity_parts.flatMap((part,pi)=>(part.motions||[]).map((motion,mi)=>{const normalizedMotion={...motion,id:motion.id||uid('motion'),name:motion.name||`动作${pi+mi+1}`,joint_id:motion.joint_id||'',position_0_percent:Number(motion.position_0_percent??0),position_100_percent:Number(motion.position_100_percent??100),mode:motion.mode==='mapping'?'mapping':'ease',rated_speed:Number(motion.rated_speed||30),enabled:motion.enabled!==false};return{...part,id:(part.motions||[]).length===1?(part.id||uid('part')):uid('part'),name:normalizedMotion.name,enabled:part.enabled!==false,motions:[normalizedMotion]}}));projectDrivesFromActivities(p);p.kinematic_closures=p.kinematic_closures.map(c=>({...c,enabled:c.enabled!==false,endpoint_a:c.endpoint_a||{layer_id:c.layer_a_id,point_mm:c.point_a_mm||[0,0,0]},endpoint_b:c.endpoint_b||{layer_id:c.layer_b_id,point_mm:c.point_b_mm||[0,0,0]},solve_joint_ids:c.solve_joint_ids||[],tolerance_mm:c.tolerance_mm||.05,max_iterations:c.max_iterations||40,damping:c.damping||.0001,max_angle_step_deg:c.max_angle_step_deg||8,max_slide_step_mm:c.max_slide_step_mm||5}));delete p.joints;delete p.closures;return p}
