function renderMeshLibrary(){const q=$('#meshSearch').value.trim().toLowerCase(),assets=(state.project.assets||[]).filter(a=>`${a.name} ${a.source_path||''}`.toLowerCase().includes(q));$('#meshFileCount').textContent=`${state.project.assets.length} FILES`;$('#meshFileList').innerHTML=assets.map(a=>{const c=normalizeRenderConfig(a.render_config);return `<div class="mesh-file-row"><button class="mesh-file" data-library-asset="${a.id}" title="双击添加到当前层级"><strong>${esc(a.source_path||a.name)}</strong><small>${formatAssetSize(a.size)} · ${esc(RENDER_MATERIAL_LABELS[c.material]||c.material)}</small></button><button class="mesh-render-config" data-render-asset="${a.id}" title="渲染配置">⚙</button></div>`}).join('')||'<div class="empty-state">尚未上传模型</div>';$$('[data-library-asset]').forEach(e=>e.ondblclick=()=>addAssetToSelectedLayer(e.dataset.libraryAsset));$$('[data-render-asset]').forEach(e=>e.onclick=()=>showRenderConfig(e.dataset.renderAsset))}
