function modelingInfoFilename(){const name=String(state.project?.name||'模型').replace(/[\\/:*?"<>|]+/g,'_').replace(/[ ._]+$/g,'')||'模型';return `${name}_建模信息.json`}
async function exportModelingInfo(){if(!state.project)return;try{if(state.dirty)await save();const includeMeasurements=window.confirm('是否同时导出测距对设置？\n\n选择“取消”时，仅导出层级/运动副、数模名称/颜色/透明度及完整驱动交换信息。');const r=await fetch(`/api/models/${encodeURIComponent(state.project.id)}/export-modeling-info?include_measurements=${includeMeasurements?'true':'false'}`);const d=await r.json().catch(()=>null);if(!r.ok)throw new Error(d?.error||`HTTP ${r.status}`);const blob=new Blob([JSON.stringify(d,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=modelingInfoFilename();document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`建模信息已导出：层级/运动副、数模名称/颜色/透明度、完整驱动信息${includeMeasurements?'、测距对':''}`,'success')}catch(e){toast(`建模信息导出失败：${e.message}`,'error')}}
async function importModelingInfo(data,mode='new'){try{const hasMeasurements=Array.isArray(data?.measurement_configuration?.pairs)&&data.measurement_configuration.pairs.length>0;const importMeasurements=hasMeasurements?window.confirm('检测到测距对设置，是否一并导入？'):false;const payload=mode==='overwrite'?{data,mode:'overwrite',model_id:state.project?.id,import_measurements:importMeasurements}:{data,mode:'new',import_measurements:importMeasurements};const result=await api('/api/models/import-modeling-info',{method:'POST',body:JSON.stringify(payload)});await loadModels(result.model.id);const layers=result.model.layers?.length||0,drives=result.model.drives?.length||0,closures=result.model.kinematic_closures?.length||0,relinked=Number(result.relinked_assets||0);const prefix=mode==='overwrite'?`已覆盖当前模型，并从现有数模库重新索引 ${relinked} 个数模`:'已新建模型；未入库数模保持外部原名';toast(`${prefix}：${layers} 个层级、${drives} 个驱动、${closures} 个闭链；完整驱动信息已参与互通${importMeasurements?'；已导入测距对':'；未导入测距对'}`,'success')}catch(e){toast(`建模信息导入失败：${e.message}`,'error')}}
function showModelingImportChoice(file,data){const root=$('#modalRoot'),dirtyNote=state.dirty?'<p class="modeling-import-warning">当前模型存在未保存修改；选择“覆盖当前模型”后这些修改会被导入内容替换。</p>':'';root.innerHTML=`<div class="modal-backdrop"><div class="modal modeling-import-modal"><h3>导入建模信息</h3><div class="modal-content"><p>文件：<strong>${esc(file.name)}</strong></p><p>请选择导入方式。覆盖模式会保留当前模型的数模库，并按外部原始文件名自动重新索引；新建模式不会伪造数模库条目。</p>${dirtyNote}<div class="modeling-import-options"><button type="button" class="modeling-import-option primary" data-import-overwrite ${state.project?'':'disabled'}><strong>覆盖当前模型</strong><small>保留当前数模库并自动索引同名数模</small></button><button type="button" class="modeling-import-option ghost" data-import-new><strong>新建模型</strong><small>创建独立模型，缺失数模继续保留原名</small></button></div></div><div class="modal-actions"><button type="button" class="button ghost" data-import-cancel>取消</button></div></div></div>`;const close=()=>{root.innerHTML=''};root.querySelector('[data-import-cancel]').onclick=close;root.querySelector('[data-import-new]').onclick=()=>{close();importModelingInfo(data,'new')};const overwrite=root.querySelector('[data-import-overwrite]');if(overwrite)overwrite.onclick=()=>{if(!state.project)return;close();importModelingInfo(data,'overwrite')}}
