async function openMaterialEditor(){if(!state.project)return;let library;try{library=await loadRenderAssets()}catch(error){toast(`材质库读取失败：${error.message}`,'error');return}if(!window.VZMaterialEditor?.open){toast('材质编辑器模块未加载','error');return}await window.VZMaterialEditor.open({model:state.project,library,reloadLibrary:async()=>{state.renderAssets=null;return await loadRenderAssets(true)},persist:async(model,{quiet=false}={})=>{const result=await api(`/api/models/${model.id}`,{method:'PUT',body:JSON.stringify({model})});state.project=normalize(result.model);state.dirty=false;$('#dirtyBadge').classList.add('hidden');renderAll();renderModelList();if(!quiet)toast('材质配置已保存','success');return typeof structuredClone==='function'?structuredClone(state.project):JSON.parse(JSON.stringify(state.project))},onClose:()=>{renderAll()}})}
async function deleteSelectedAsset(){const id=state.assetModalSelection,asset=state.project.assets.find(a=>a.id===id);if(!asset||!confirm(`从数模库删除“${asset.source_path||asset.name}”？层级中的当前文件名会保持原样，仅解除与数模库的关联。`))return;try{state.project=normalize((await api(`/api/models/${state.project.id}/assets/${id}`,{method:'DELETE'})).model);state.assetModalSelection=null;renderAll();renderAssetManager();await loadModels(state.project.id);toast('数模已从库删除；相关层级文件名保持原样','success')}catch(error){toast(error.message,'error')}}
