async function uploadMeshFile(file,relativePath=''){if(file.size<=0)throw new Error(`${file.name} 是空文件`);if(file.size>2*1024*1024*1024)throw new Error(`${file.name} 超过 2 GiB`);const params=new URLSearchParams({filename:file.name});if(relativePath)params.set('relative_path',relativePath);const url=`/api/models/${state.project.id}/assets?${params.toString()}`;const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:file}),d=await r.json().catch(()=>({error:`HTTP ${r.status}`}));if(!r.ok)throw new Error(d.error||'数模上传失败');return d}
function meshUploadProgress(total,label='数模上传'){let e=$('#meshUploadProgressToast');if(!e){e=document.createElement('div');e.id='meshUploadProgressToast';e.className='toast progress-toast';e.innerHTML='<div class="progress-toast-head"><b data-upload-title></b><span data-progress-text>0%</span></div><div class="progress-track"><i data-progress-bar></i></div><small data-progress-message></small>';$('#toastRegion').appendChild(e)}e.querySelector('[data-upload-title]').textContent=label;e.querySelector('[data-progress-message]').textContent=`准备上传 ${total} 个 STL/OBJ`;e.querySelector('[data-progress-text]').textContent='0%';e.querySelector('[data-progress-bar]').style.width='0%';e.classList.remove('error');return e}
async function uploadMeshSelection(fileList){const all=[...fileList],files=all.filter(file=>/\.(stl|obj)$/i.test(file.name));if(!files.length){toast('所选内容中没有 STL/OBJ 文件','error');return}if(state.dirty)await save();const e=meshUploadProgress(files.length);const failed=[];let uploaded=0;for(let i=0;i<files.length;i++){const file=files[i];e.querySelector('[data-progress-message]').textContent=`${i+1}/${files.length} · ${file.name}`;try{state.project=normalize((await uploadMeshFile(file)).model);uploaded++}catch(error){failed.push(`${file.name}: ${error.message}`)}const percent=Math.round((i+1)/files.length*100);e.querySelector('[data-progress-text]').textContent=`${percent}%`;e.querySelector('[data-progress-bar]').style.width=`${percent}%`}renderAll();renderAssetManager();await loadModels(state.project.id);renderAssetManager();if(failed.length){e.classList.add('error');e.querySelector('[data-progress-message]').textContent=`完成 ${uploaded} 个，失败 ${failed.length} 个`;setTimeout(()=>e.remove(),4200);toast(`上传完成：成功 ${uploaded} 个，失败 ${failed.length} 个。${failed.slice(0,2).join('；')}`,'error')}else{e.querySelector('[data-progress-message]').textContent=`已上传 ${uploaded} 个 STL/OBJ`;setTimeout(()=>e.remove(),900);toast(`已上传 ${uploaded} 个 STL/OBJ`,'success')}}
