function progressToast(message='任务准备中…',title='VZ 任务'){let e=$('#generationProgressToast');if(!e){e=document.createElement('div');e.id='generationProgressToast';e.className='toast progress-toast';e.innerHTML='<div class="progress-toast-head"><b data-progress-title>VZ 任务</b><span data-progress-text>0%</span></div><div class="progress-track"><i data-progress-bar></i></div><small data-progress-message></small>';$('#toastRegion').appendChild(e)}e.querySelector('[data-progress-title]').textContent=title;e.querySelector('[data-progress-message]').textContent=message;return e}
async function waitForJob(jobId,onProgress=null){const e=progressToast();while(true){const job=await api(`/api/jobs/${jobId}`);const percent=Math.round(Number(job.progress||0)*100),message=job.message||'处理中';e.querySelector('[data-progress-text]').textContent=`${percent}%`;e.querySelector('[data-progress-bar]').style.width=`${percent}%`;e.querySelector('[data-progress-message]').textContent=message;if(onProgress)onProgress(percent,message,job);if(job.status==='completed'){setTimeout(()=>e.remove(),900);return job.result}if(job.status==='failed'){e.classList.add('error');setTimeout(()=>e.remove(),4200);throw new Error(job.error?.message||job.message||'任务失败')}await new Promise(r=>setTimeout(r,450))}}
async function saveUrlToLocalPath(url,suggestedName){let handle=null;try{if(typeof window.showSaveFilePicker==='function')handle=await window.showSaveFilePicker({suggestedName,types:[{description:'VZ 离线动画 HTML',accept:{'text/html':['.html']}}]})}catch(error){if(error?.name==='AbortError')return false;console.warn('另存为选择器不可用，退回浏览器下载',error)}const response=await fetch(url);if(!response.ok)throw new Error(`下载失败：HTTP ${response.status}`);const blob=await response.blob();if(handle){const writable=await handle.createWritable();await writable.write(blob);await writable.close();return true}const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=suggestedName;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(link.href),1200);return true}
function openRenderModal(info){const root=$('#modalRoot'),safeName=(state.project?.name||'模型').replace(/[\\/:*?"<>|]+/g,'_').replace(/^\.+|\.+$/g,'')||'模型';root.innerHTML=`<div class="modal-backdrop render-player-backdrop"><div class="modal render-player-modal"><header class="render-player-head"><div><h3>${esc(state.project?.name||'模型')} · ${esc(info.title)}</h3><small data-render-status>正在准备渲染…</small></div><div class="render-player-actions"><button class="button primary" data-render-download disabled>下载</button><button class="button ghost" data-render-close>关闭</button></div></header><div class="render-player-body"><div class="render-player-loading" data-render-loading>正在生成 ${esc(info.title)}…</div><iframe data-render-frame title="${esc(info.title)}动画" hidden></iframe></div></div></div>`;const modal={root,frame:root.querySelector('[data-render-frame]'),loading:root.querySelector('[data-render-loading]'),status:root.querySelector('[data-render-status]'),download:root.querySelector('[data-render-download]'),close:root.querySelector('[data-render-close]'),url:'',objectUrl:'',filename:`${safeName}_${info.title}.html`};modal.close.onclick=()=>{if(modal.objectUrl)URL.revokeObjectURL(modal.objectUrl);root.innerHTML=''};modal.download.onclick=async()=>{if(!modal.url)return;try{modal.download.disabled=true;modal.download.textContent='保存中…';const saved=await saveUrlToLocalPath(modal.url,modal.filename);if(saved)toast('动画已保存到本地','success')}catch(error){toast(error.message,'error')}finally{if(modal.download.isConnected){modal.download.disabled=!modal.url;modal.download.textContent='下载'}}};return modal}
$('#simulateButton').onclick=async()=>{const b=$('#simulateButton');try{if(state.dirty)await save();b.disabled=true;b.textContent='仿真中…';progressToast('正在执行 MuJoCo 仿真','MuJoCo 仿真');const d=await api('/api/simulate',{method:'POST',body:JSON.stringify({model_id:state.project.id,use_project_schedule:true})});const result=await waitForJob(d.job_id);$('#simulationResult').classList.remove('hidden');$('#simulationResult').innerHTML=`<h3>MuJoCo 仿真完成</h3><pre>${esc(JSON.stringify(result.summary,null,2))}</pre>`;toast('MuJoCo 仿真完成','success')}catch(e){toast(e.message,'error')}finally{b.disabled=false;b.textContent='▶ MuJoCo 仿真'}};
const RENDER_QUALITY_INFO={fast:{button:'#fastExportButton',title:'快速渲染',progress:'快速渲染：仅生成 1 个渲染样本，并报告该单帧实际渲染时间'},perfect:{button:'#perfectExportButton',title:'高质量渲染',progress:'高质量渲染：PBR 贴图 + 环境反射 + 真实阴影 + 高保真网格'}};
async function exportFastBenchmark(info,b,modal){const progress=progressToast(info.progress,info.title),setProgress=(percent,message)=>{if(!progress.isConnected)return;progress.querySelector('[data-progress-text]').textContent=`${percent}%`;progress.querySelector('[data-progress-bar]').style.width=`${percent}%`;progress.querySelector('[data-progress-message]').textContent=message};try{setProgress(12,'准备单帧所需仿真数据（不渲染）');if(modal.status.isConnected)modal.status.textContent='准备单帧所需仿真数据（不渲染）';const prepared=await api('/api/fast-render-warmup',{method:'POST',body:JSON.stringify({model_id:state.project.id})});setProgress(38,'正在渲染唯一 1 帧');if(modal.status.isConnected)modal.status.textContent='正在渲染唯一 1 帧';const transferStarted=performance.now();const response=await fetch('/api/fast-render-benchmark',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model_id:state.project.id,benchmark_id:prepared.benchmark_id})});if(!response.ok){const error=await response.json().catch(()=>({error:`HTTP ${response.status}`}));throw new Error(error.error||'快速渲染失败')}setProgress(88,'单帧渲染完成 · 正在接收 HTML');const html=await response.text(),transferMs=performance.now()-transferStarted,renderMs=Number(response.headers.get('X-VZ-Render-Time-Ms'));if(Number(response.headers.get('X-VZ-Render-Samples'))!==1||Number(response.headers.get('X-VZ-Warmup-Renders'))!==0)throw new Error('服务端未按单帧快速渲染协议执行');const singleMs=Number.isFinite(renderMs)?renderMs:transferMs;setProgress(100,`完成 · 单帧 ${singleMs.toFixed(2)} ms`);if(!modal.root.querySelector('[data-render-frame]'))return;if(modal.objectUrl)URL.revokeObjectURL(modal.objectUrl);modal.objectUrl=URL.createObjectURL(new Blob([html],{type:'text/html'}));modal.url=modal.objectUrl;modal.frame.src=modal.objectUrl;modal.frame.hidden=false;modal.loading.classList.add('hidden');modal.status.textContent=`渲染完成 · 单帧 ${singleMs.toFixed(2)} ms · 含传输 ${transferMs.toFixed(2)} ms`;modal.download.disabled=false;$('#simulationResult').classList.add('hidden');$('#simulationResult').innerHTML='';toast(`快速渲染已完成：单帧 ${singleMs.toFixed(2)} ms`,'success')}catch(error){progress.classList.add('error');setProgress(100,`失败：${error.message}`);throw error}finally{setTimeout(()=>progress.remove(),progress.classList.contains('error')?4200:900)}}
async function exportAnimation(quality){const info=RENDER_QUALITY_INFO[quality]||RENDER_QUALITY_INFO.fast,b=$(info.button),modal=openRenderModal(info);try{if(state.dirty)await save();b.disabled=true;if(quality==='fast'){await exportFastBenchmark(info,b,modal);return}const configured=(state.project.assets||[]).filter(a=>{const c=normalizeRenderConfig(a.render_config);return c.base_color_map||c.normal_map||c.roughness_map||c.metallic_map||c.ao_map}).length,env=normalizeRenderScene(state.project.render_scene).environment_map;if(!configured&&!env)toast('高质量渲染未配置外部 PBR/环境素材，将使用内置摄影棚 PBR','');progressToast(info.progress,info.title);const d=await api('/api/export-animation',{method:'POST',body:JSON.stringify({model_id:state.project.id,quality})});const result=await waitForJob(d.job_id,(percent,message)=>{if(modal.status.isConnected)modal.status.textContent=`${percent}% · ${message}`});if(!modal.root.querySelector('[data-render-frame]'))return;modal.url=result.animation_url;modal.frame.src=result.animation_url;modal.frame.hidden=false;modal.loading.classList.add('hidden');modal.status.textContent='渲染完成';modal.download.disabled=false;$('#simulationResult').classList.add('hidden');$('#simulationResult').innerHTML='';toast(`${info.title}已完成`,'success')}catch(e){if(modal.loading.isConnected)modal.loading.textContent=`渲染失败：${e.message}`;if(modal.status.isConnected)modal.status.textContent='渲染失败';toast(e.message,'error')}finally{b.disabled=false}}
$('#fastExportButton').onclick=()=>exportAnimation('fast');$('#perfectExportButton').onclick=()=>exportAnimation('perfect');
$$('[data-scene-coordinate]').forEach(input=>input.onchange=()=>commitSceneCoordinate(input.dataset.sceneCoordinate));$('#deleteModelButton').onclick=async()=>{if(!state.project)return;const managed=!!state.project._hub_source,message=managed?`从 VZ 取消推送并移除“${state.project.name}”？\n\nMuJoCoHub 源模型不会被删除；Hub 推送开关会同步关闭，VZ 侧 15 分钟内可恢复。`:`从 VZ 项目库移除“${state.project.name}”？15 分钟内可恢复。`;if(!confirm(message))return;try{const removed=await api(`/api/models/${state.project.id}`,{method:'DELETE'});state.project=null;await loadModels();if(managed&&removed?.hub_sync?.synced===false)toast('模型已从 VZ 移除；Hub 状态回传暂未完成，Hub 会在目录对账时自动关闭推送','');else toast(managed?'已取消推送并从 VZ 移除模型，Hub 推送状态已同步':'已从 VZ 项目库移除模型','success')}catch(e){toast(e.message,'error')}};$('#openClientButton').onclick=()=>window.open('/client','_blank','noopener');loadModels().catch(e=>toast(e.message,'error'));

$('#modelNameInput').onchange=e=>{if(!state.project)return;const name=e.target.value.trim();if(!name){e.target.value=state.project.name;toast('模型名称不能为空','error');return}state.project.name=name;markDirty();$('#projectRevision').textContent=`${state.project.name} · 修订 ${state.project.revision}`;renderModelList()};
$('#perfectRenderSettingsButton').onclick=()=>showHtmlRenderSettings();

// Display the actual browser-visible VZ port (also valid behind an HTTPS proxy).
const vzPortLabel = document.getElementById("vzActivePort");
if (vzPortLabel) vzPortLabel.textContent = `无需账号 · 端口 ${location.port || (location.protocol === "https:" ? "443" : "80")}`;
